import type { IsoTimestamp, OrgId } from "@/types/common";

/** Fields the renewal job and mid-period plan changes write back. */
export type SubscriptionBillingPatch = {
  plan?: PlanId;
  interval?: BillingInterval;
  status?: SubscriptionStatus;
  currentPeriodStart?: IsoTimestamp;
  currentPeriodEnd?: IsoTimestamp;
  /** `null` clears a pending cancellation. Omit the key to leave it alone. */
  cancelAt?: IsoTimestamp | null;
};

/**
 * Patches the billing columns of an org's subscription. `now` stamps
 * `updatedAt` so a renewal driven by an explicit clock does not depend on the
 * wall clock.
 */
export async function updateSubscriptionBilling(
  orgId: OrgId,
  patch: SubscriptionBillingPatch,
  now: Date,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      ...(patch.plan === undefined ? {} : { plan: patch.plan }),
      ...(patch.interval === undefined ? {} : { interval: patch.interval }),
      ...(patch.status === undefined ? {} : { status: patch.status }),
      ...(patch.currentPeriodStart === undefined
        ? {}
        : { currentPeriodStart: patch.currentPeriodStart }),
      ...(patch.currentPeriodEnd === undefined
        ? {}
        : { currentPeriodEnd: patch.currentPeriodEnd }),
      ...(patch.cancelAt === undefined ? {} : { cancelAt: patch.cancelAt }),
      updatedAt: toIsoTimestamp(now),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/**
 * Every workspace that still has a subscription, archived workspaces excluded.
 * One id per org even if a duplicate subscription row exists — updates are
 * keyed by org, so processing the org twice would invoice the same period
 * twice. The renewal job has to see all of them, so this is not batched.
 */
export async function listBillableOrgIds(): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: subscriptions.orgId })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(isNull(organizations.archivedAt))
    .all();

  const seen = new Set<string>();
  const orgIds: OrgId[] = [];
  for (const row of rows) {
    if (seen.has(row.orgId)) continue;
    seen.add(row.orgId);
    orgIds.push(brandId<OrgId>(row.orgId));
  }
  orgIds.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return orgIds;
}

