export type IssueInvoiceInput = {
  amountCents: number;
  periodStart: IsoTimestamp;
  periodEnd: IsoTimestamp;
  actorId: UserId | null;
  occurredAt: IsoTimestamp;
};

/**
 * Persists one invoice and announces it once: the domain event, a single
 * audit row (subject = the workspace) and one notification to the owner.
 * A charge of zero cents produces no invoice and no announcement.
 *
 * The owner's notification is sent with no actor so it is still delivered
 * when the owner is the person who made the change — `notify` otherwise
 * suppresses a recipient who is also the actor.
 */
export async function issueInvoice(
  orgId: OrgId,
  input: IssueInvoiceInput,
): Promise<Invoice | null> {
  if (input.amountCents <= 0) return null;

  const used = new Set(await invoiceRepo.listInvoiceNumbers(orgId));
  let sequence = used.size + 1;
  let number = formatInvoiceNumber(sequence);
  while (used.has(number)) {
    sequence += 1;
    number = formatInvoiceNumber(sequence);
  }

  const invoice = await invoiceRepo.insertInvoice(orgId, {
    orgId,
    number,
    amountCents: input.amountCents,
    currency: "usd",
    periodStart: input.periodStart,
    periodEnd: input.periodEnd,
    paidAt: null,
  });

  await emit("billing.invoice_issued", {
    orgId,
    actorId: input.actorId,
    occurredAt: input.occurredAt,
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  });

  await record(orgId, "billing.invoice_issued", {
    actorId: input.actorId,
    subjectKind: "subscription",
    subjectId: orgId,
    projectId: null,
    summary: `Issued invoice ${invoice.number} for ${invoice.amountCents} cents`,
    metadata: {
      invoiceId: invoice.id,
      invoiceNumber: invoice.number,
      amountCents: invoice.amountCents,
    },
  });

  const org = await orgRepo.findOrgById(orgId);
  if (org && org.archivedAt === null) {
    await notify(orgId, "invoice_issued", [org.ownerId], {
      title: `Invoice ${invoice.number}`,
      body: `Invoice ${invoice.number} for ${invoice.amountCents} cents was issued.`,
      href: "/settings/billing/invoices",
      actorId: null,
    });
  }

  return invoice;
}

function formatInvoiceNumber(sequence: number): string {
  return `INV-${String(sequence).padStart(4, "0")}`;
}

