/**
 * Renews subscriptions whose period has ended and ends cancellations that
 * have come due. Every renewed paid period is invoiced; the free plan's
 * periods move on the same way without an invoice.
 *
 * Must call (do not reimplement): emit, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { addBillingInterval, fullPeriodCents } from "@/lib/billing-period";
import { parseIso } from "@/lib/date";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { issueInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";
import type { OrgId } from "@/types/common";

/**
 * A subscription stranded centuries in the past would otherwise spin. Real
 * calendars stay far under this; hitting it means the period math failed to
 * move forward and the workspace should be reported as failed.
 */
const MAX_PERIODS_PER_ORG = 10_000;

const logger = createLogger("billing-renewal-job");

/**
 * One pass over every live workspace. Archived workspaces are skipped
 * entirely. `trialing` and `past_due` subscriptions are left for the
 * trial-expiry job. Running the job again at the same instant is a no-op:
 * periods have already been advanced past `now`, cancellations cleared, and
 * each invoice was written once.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const orgIds = await subscriptionRepo.listBillableOrgIds();

    for (const orgId of orgIds) {
      try {
        result.processed += await renewWorkspace(orgId, now);
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/**
 * Applies a due cancellation, then advances every elapsed period. Returns how
 * many of those steps ran. A workspace that is not due contributes zero, so
 * a second pass at the same instant adds nothing.
 */
async function renewWorkspace(orgId: OrgId, now: Date): Promise<number> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org || org.archivedAt !== null) return 0;

  let current = await subscriptionRepo.findSubscription(orgId);
  if (!current) return 0;

  const stamp = toIsoTimestamp(now);
  let steps = 0;

  if (current.status === "canceled") {
    if (
      current.cancelAt === null ||
      parseIso(current.cancelAt).getTime() > now.getTime()
    ) {
      // Before the cancellation date nothing happens, even if the period
      // already ended — the subscription is not renewed in the meantime.
      return 0;
    }

    const from = current.plan;
    const periodStart = current.cancelAt;
    const periodEnd = toIsoTimestamp(
      addBillingInterval(parseIso(periodStart), "monthly"),
    );
    current = await subscriptionRepo.updateSubscriptionBilling(
      orgId,
      {
        plan: "free",
        interval: "monthly",
        status: "active",
        cancelAt: null,
        currentPeriodStart: periodStart,
        currentPeriodEnd: periodEnd,
      },
      now,
    );
    await orgRepo.updateOrgPlan(orgId, "free", now);
    await emit("billing.plan_changed", {
      orgId,
      actorId: null,
      occurredAt: stamp,
      from,
      to: "free",
    });
    steps += 1;
  } else if (current.status !== "active") {
    return 0;
  }

  let advanced = 0;
  while (parseIso(current.currentPeriodEnd).getTime() <= now.getTime()) {
    advanced += 1;
    if (advanced > MAX_PERIODS_PER_ORG) {
      throw new Error(
        `Billing renewal for org ${orgId} exceeded ${MAX_PERIODS_PER_ORG} periods`,
      );
    }
    current = await advanceOnePeriod(current, now, stamp);
    steps += 1;
  }

  return steps;
}

/**
 * Opens the next period, starting exactly where the previous one ended, and
 * invoices a paid plan for that period's full charge at the seat count in
 * force now. The free plan moves forward with no invoice.
 */
async function advanceOnePeriod(
  current: Subscription,
  now: Date,
  occurredAt: ReturnType<typeof toIsoTimestamp>,
): Promise<Subscription> {
  const periodStart = current.currentPeriodEnd;
  const periodEndDate = addBillingInterval(
    parseIso(periodStart),
    current.interval,
  );
  if (periodEndDate.getTime() <= parseIso(periodStart).getTime()) {
    throw new Error(
      `Billing period for org ${current.orgId} did not advance`,
    );
  }
  const periodEnd = toIsoTimestamp(periodEndDate);

  if (current.plan !== "free") {
    const amountCents = fullPeriodCents(
      getPlanLimits(current.plan).priceCentsPerSeatMonthly,
      current.seats,
      current.interval,
    );
    await issueInvoice(current.orgId, {
      amountCents,
      periodStart,
      periodEnd,
      actorId: null,
      occurredAt,
    });
  }

  return subscriptionRepo.updateSubscriptionBilling(
    current.orgId,
    { currentPeriodStart: periodStart, currentPeriodEnd: periodEnd },
    now,
  );
}

