/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const currentPlan = await planFor(input.orgId);

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const now = new Date();
  const occurredAt = toIsoTimestamp(now);
  const current = await subscriptionRepo.findSubscription(input.orgId);
  if (!current) {
    throw new Error(`Subscription for org ${input.orgId} not found`);
  }

  // Choosing a plan during a trial keeps that trial period and is not
  // invoiced — the first invoice is the renewal that closes the trial.
  // Leaving the free plan starts a fresh period now and is invoiced in full.
  const leavingFree =
    current.status !== "trialing" &&
    current.plan === "free" &&
    input.plan !== "free";

  let subscription: Subscription;
  if (leavingFree) {
    const periodStart = occurredAt;
    const periodEnd = toIsoTimestamp(addBillingInterval(now, input.interval));
    subscription = await subscriptionRepo.updateSubscriptionBilling(
      input.orgId,
      {
        plan: input.plan,
        interval: input.interval,
        status: "active",
        currentPeriodStart: periodStart,
        currentPeriodEnd: periodEnd,
      },
      now,
    );
    await issueInvoice(input.orgId, {
      amountCents: fullPeriodCents(
        getPlanLimits(input.plan).priceCentsPerSeatMonthly,
        current.seats,
        input.interval,
      ),
      periodStart,
      periodEnd,
      actorId: actor.userId,
      occurredAt,
    });
  } else {
    subscription = await subscriptionRepo.updateSubscriptionPlan(
      input.orgId,
      input.plan,
      input.interval,
    );

    // The period itself stays put, so the months in it are the interval it
    // already had. Only a strictly more expensive paid plan is charged, and
    // only while the subscription is active.
    const priceDiff =
      getPlanLimits(input.plan).priceCentsPerSeatMonthly -
      getPlanLimits(current.plan).priceCentsPerSeatMonthly;
    if (
      current.status === "active" &&
      current.plan !== "free" &&
      input.plan !== "free" &&
      priceDiff > 0
    ) {
      const periodStart = parseIso(current.currentPeriodStart);
      const periodEnd = parseIso(current.currentPeriodEnd);
      await issueInvoice(input.orgId, {
        amountCents: prorateCents(
          priceDiff * current.seats * monthsInInterval(current.interval),
          daysRemaining(now, periodEnd),
          wholeDaysInPeriod(periodStart, periodEnd),
        ),
        periodStart: current.currentPeriodStart,
        periodEnd: current.currentPeriodEnd,
        actorId: actor.userId,
        occurredAt,
      });
    }
  }

  if (input.plan !== current.plan) {
    await orgRepo.updateOrgPlan(input.orgId, input.plan, now);
  }

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  return subscription;
}

