describe("billing period arithmetic", () => {
  it("clamps month ends and carries the clamped day forward", () => {
    const jan31 = new Date("2025-01-31T15:30:00.000Z");
    const feb = addBillingInterval(jan31, "monthly");
    expect(feb.toISOString()).toBe("2025-02-28T15:30:00.000Z");
    expect(addBillingInterval(feb, "monthly").toISOString()).toBe(
      "2025-03-28T15:30:00.000Z",
    );

    const leap = new Date("2024-01-31T00:00:00.000Z");
    expect(addBillingInterval(leap, "monthly").toISOString()).toBe(
      "2024-02-29T00:00:00.000Z",
    );

    const leapDay = new Date("2024-02-29T08:00:00.000Z");
    const nextYear = addBillingInterval(leapDay, "annual");
    expect(nextYear.toISOString()).toBe("2025-02-28T08:00:00.000Z");
    expect(addBillingInterval(nextYear, "annual").toISOString()).toBe(
      "2026-02-28T08:00:00.000Z",
    );
  });

  it("counts started days and floors prorations", () => {
    const end = new Date("2026-04-01T00:00:00.000Z");
    const now = new Date(end.getTime() - (14 * 24 + 22) * 60 * 60 * 1000);
    expect(daysRemaining(now, end)).toBe(15);
    expect(daysRemaining(end, end)).toBe(0);
    expect(daysRemaining(new Date(end.getTime() + 1), end)).toBe(0);
    const start = new Date("2026-03-01T00:00:00.000Z");
    expect(wholeDaysInPeriod(start, end)).toBe(31);
    expect(prorateCents(100, 1, 3)).toBe(33);
    expect(prorateCents(1, 1, 3)).toBe(0);
  });
});

