 * Billing-period arithmetic.
 *
 * A period runs from its start up to its end. Monthly and annual ends land on
 * the same day-of-month (and time of day) in the destination month, clamped to
 * that month's last day when the day does not exist. The next period starts
 * exactly where this one ended, so a clamped day carries forward — 31 January
 * becomes 28 February, and that period then ends on 28 March, not 31 March.
 */
import type { BillingInterval } from "@/types/billing";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

function daysInUtcMonth(year: number, monthIndex: number): number {
  return new Date(Date.UTC(year, monthIndex + 1, 0)).getUTCDate();
}

/** The end of the single period that begins at `start`. */
export function addBillingInterval(start: Date, interval: BillingInterval): Date {
  const months = interval === "annual" ? 12 : 1;
  const monthIndex = start.getUTCMonth() + months;
  const year = start.getUTCFullYear() + Math.floor(monthIndex / 12);
  const month = monthIndex % 12;
  const day = Math.min(start.getUTCDate(), daysInUtcMonth(year, month));

  return new Date(
    Date.UTC(
      year,
      month,
      day,
      start.getUTCHours(),
      start.getUTCMinutes(),
      start.getUTCSeconds(),
      start.getUTCMilliseconds(),
    ),
  );
}

/** Whole months a period of this interval covers: 1 monthly, 12 annual. */
export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * Whole days from `start` to `end`, rounded to the nearest day and at least
 * one. Matching times of day land on an exact day count; the floor of one
 * keeps a degenerate period from dividing a proration by zero.
 */
export function wholeDaysInPeriod(start: Date, end: Date): number {
  const rounded = Math.round((end.getTime() - start.getTime()) / MS_PER_DAY);
  return Math.max(1, rounded);
}

/**
 * Whole or started days from `now` until `periodEnd`. 14 days and 22 hours
 * count as 15. None remain once the period end has been reached.
 */
export function daysRemaining(now: Date, periodEnd: Date): number {
  const remaining = periodEnd.getTime() - now.getTime();
  if (remaining <= 0) return 0;
  return Math.ceil(remaining / MS_PER_DAY);
}

/** Full-period amount scaled by the days left, rounded down to whole cents. */
export function prorateCents(
  fullPeriodCents: number,
  daysLeft: number,
  periodDays: number,
): number {
  if (fullPeriodCents <= 0 || daysLeft <= 0 || periodDays <= 0) return 0;
  return Math.floor((fullPeriodCents * daysLeft) / periodDays);
}

/** Monthly price per seat × seats × the months in the interval, in cents. */
export function fullPeriodCents(
  priceCentsPerSeatMonthly: number,
  seats: number,
  interval: BillingInterval,
): number {
  return priceCentsPerSeatMonthly * seats * monthsInInterval(interval);
}
