    // already had. Only a strictly more expensive paid plan is charged, and
    // only while the subscription is active.
    const priceDiff =
      getPlanLimits(input.plan).priceCentsPerSeatMonthly -
      getPlanLimits(current.plan).priceCentsPerSeatMonthly;
    if (
      current.status === "active" &&
      current.plan !== "free" &&
      input.plan !== "free" &&
      priceDiff > 0
