let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("billing period arithmetic", () => {
  it("clamps month ends and carries the clamped day forward", () => {
    const jan31 = new Date("2025-01-31T15:30:00.000Z");
    const feb = addBillingInterval(jan31, "monthly");
    expect(feb.toISOString()).toBe("2025-02-28T15:30:00.000Z");
    expect(addBillingInterval(feb, "monthly").toISOString()).toBe(
      "2025-03-28T15:30:00.000Z",
    );

    const leap = new Date("2024-01-31T00:00:00.000Z");
    expect(addBillingInterval(leap, "monthly").toISOString()).toBe(
      "2024-02-29T00:00:00.000Z",
    );

    const leapDay = new Date("2024-02-29T08:00:00.000Z");
    const nextYear = addBillingInterval(leapDay, "annual");
    expect(nextYear.toISOString()).toBe("2025-02-28T08:00:00.000Z");
    expect(addBillingInterval(nextYear, "annual").toISOString()).toBe(
      "2026-02-28T08:00:00.000Z",
    );
  });

  it("counts started days and floors prorations", () => {
    const end = new Date("2026-04-01T00:00:00.000Z");
    const now = new Date(end.getTime() - (14 * 24 + 22) * 60 * 60 * 1000);
    expect(daysRemaining(now, end)).toBe(15);
    expect(daysRemaining(end, end)).toBe(0);
    expect(daysRemaining(new Date(end.getTime() + 1), end)).toBe(0);
    const start = new Date("2026-03-01T00:00:00.000Z");
    expect(wholeDaysInPeriod(start, end)).toBe(31);
    expect(prorateCents(100, 1, 3)).toBe(33);
    expect(prorateCents(1, 1, 3)).toBe(0);
  });
});

describe("renewal job", () => {
  it("renews three elapsed monthly periods and is replay-safe", async () => {
    const tenant = await createTenant("renew-3", "starter");
    await subscriptionRepo.updateSubscriptionBilling(
      tenant.org.id,
      {
        status: "active",
        interval: "monthly",
        currentPeriodStart: toIsoTimestamp(new Date("2026-01-31T10:00:00.000Z")),
        currentPeriodEnd: toIsoTimestamp(new Date("2026-02-28T10:00:00.000Z")),
        seats: 2,
      },
      new Date("2026-01-31T10:00:00.000Z"),
    );
    // starter insert sets seats to 1; patch above doesn't include a seats writer.
    // update seat count separately.
    await subscriptionRepo.updateSeatCount(tenant.org.id, 2);

    const now = new Date("2026-05-15T10:00:00.000Z");
    const seen: unknown[] = [];
    const off = subscribe("billing.invoice_issued", (payload) => {
      seen.push(payload);
    });

    const first = await runBillingRenewalJob(now);
    const second = await runBillingRenewalJob(now);
    off();

    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    // Feb 28 → Mar 28 → Apr 28 → May 28. May 28 is after May 15, so three periods.
    expect(sub?.currentPeriodStart).toBe("2026-04-28T10:00:00.000Z");
    expect(sub?.currentPeriodEnd).toBe("2026-05-28T10:00:00.000Z");
    expect(sub?.status).toBe("active");
    expect(first.processed).toBe(3);
    expect(first.failed).toBe(0);
    expect(second.processed).toBe(0);

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.map((invoice) => invoice.amountCents)).toEqual([
      1800, 1800, 1800,
    ]);
    expect(invoices.map((invoice) => invoice.periodStart)).toEqual([
      "2026-04-28T10:00:00.000Z",
      "2026-03-28T10:00:00.000Z",
      "2026-02-28T10:00:00.000Z",
    ]);
    expect(invoices.every((invoice) => invoice.currency === "usd" && invoice.paidAt === null)).toBe(true);
    expect(new Set(invoices.map((invoice) => invoice.number)).size).toBe(3);
    expect(seen).toHaveLength(3);

    const activity = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["billing.invoice_issued"],
      limit: 20,
      cursor: null,
    });
    expect(activity.items).toHaveLength(3);
    expect(activity.items[0]?.subjectKind).toBe("subscription");
    expect(activity.items[0]?.subjectId).toBe(tenant.org.id);

    const notes = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 20,
      cursor: null,
    });
    expect(notes.items.filter((note) => note.kind === "invoice_issued")).toHaveLength(3);

    const memberNotes = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      limit: 20,
      cursor: null,
    });
    expect(memberNotes.items.filter((note) => note.kind === "invoice_issued")).toHaveLength(0);
  });

  it("moves a free plan forward without invoices", async () => {
    const tenant = await createTenant("renew-free", "free");
    await subscriptionRepo.updateSubscriptionBilling(
      tenant.org.id,
      {
        status: "active",
        currentPeriodStart: toIsoTimestamp(new Date("2026-01-01T00:00:00.000Z")),
        currentPeriodEnd: toIsoTimestamp(new Date("2026-02-01T00:00:00.000Z")),
      },
      new Date("2026-01-01T00:00:00.000Z"),
    );

    await runBillingRenewalJob(new Date("2026-03-15T00:00:00.000Z"));
    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(sub?.currentPeriodStart).toBe("2026-03-01T00:00:00.000Z");
    expect(sub?.currentPeriodEnd).toBe("2026-04-01T00:00:00.000Z");
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
  });

  it("leaves trialing and past_due alone and skips archived workspaces", async () => {
    const trialing = await createTenant("renew-trial", "growth");
    const past = await createTenant("renew-past", "growth");
    await subscriptionRepo.updateSubscriptionBilling(
      past.org.id,
      {
        status: "past_due",
        currentPeriodEnd: toIsoTimestamp(new Date("2026-01-01T00:00:00.000Z")),
      },
      new Date("2026-01-01T00:00:00.000Z"),
    );
    const archived = await createTenant("renew-archived", "starter");
    await subscriptionRepo.updateSubscriptionBilling(
      archived.org.id,
      {
        status: "active",
        currentPeriodEnd: toIsoTimestamp(new Date("2026-01-01T00:00:00.000Z")),
      },
      new Date("2026-01-01T00:00:00.000Z"),
    );
    await orgRepo.archiveOrg(archived.org.id);

    const trialBefore = await subscriptionRepo.findSubscription(trialing.org.id);
    await runBillingRenewalJob(new Date("2027-01-01T00:00:00.000Z"));

    const trialAfter = await subscriptionRepo.findSubscription(trialing.org.id);
    expect(trialAfter?.status).toBe("trialing");
    expect(trialAfter?.currentPeriodEnd).toBe(trialBefore?.currentPeriodEnd);
    expect(await invoiceRepo.listInvoices(trialing.org.id)).toHaveLength(0);

    const pastAfter = await subscriptionRepo.findSubscription(past.org.id);
    expect(pastAfter?.status).toBe("past_due");
    expect(pastAfter?.currentPeriodEnd).toBe("2026-01-01T00:00:00.000Z");

    const archivedAfter = await subscriptionRepo.findSubscription(archived.org.id);
    expect(archivedAfter?.currentPeriodEnd).toBe("2026-01-01T00:00:00.000Z");
    expect(await invoiceRepo.listInvoices(archived.org.id)).toHaveLength(0);
  });

  it("ends a cancellation on its date and does not invoice", async () => {
    const tenant = await createTenant("renew-cancel", "growth");
    await subscriptionRepo.updateSubscriptionBilling(
      tenant.org.id,
      {
        status: "canceled",
        cancelAt: toIsoTimestamp(new Date("2026-04-10T12:00:00.000Z")),
        currentPeriodStart: toIsoTimestamp(new Date("2026-03-01T12:00:00.000Z")),
        currentPeriodEnd: toIsoTimestamp(new Date("2026-04-01T12:00:00.000Z")),
        interval: "annual",
      },
      new Date("2026-03-01T12:00:00.000Z"),
    );

    const early = await runBillingRenewalJob(new Date("2026-04-01T12:00:00.000Z"));
    const still = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(early.processed).toBe(0);
    expect(still?.status).toBe("canceled");
    expect(still?.plan).toBe("growth");

    const seen: unknown[] = [];
    const off = subscribe("billing.plan_changed", (payload) => {
      seen.push(payload);
    });
    await runBillingRenewalJob(new Date("2026-06-20T12:00:00.000Z"));
    await runBillingRenewalJob(new Date("2026-06-20T12:00:00.000Z"));
    off();

    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(sub?.plan).toBe("free");
    expect(sub?.status).toBe("active");
    expect(sub?.cancelAt).toBeNull();
    expect(sub?.interval).toBe("monthly");
    // Apr 10 → May 10 → Jun 10 → Jul 10. Jul 10 is after Jun 20.
    expect(sub?.currentPeriodStart).toBe("2026-06-10T12:00:00.000Z");
    expect(sub?.currentPeriodEnd).toBe("2026-07-10T12:00:00.000Z");
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      from: "growth",
      to: "free",
      actorId: null,
      orgId: tenant.org.id,
    });
    const org = await orgRepo.findOrgById(tenant.org.id);
    expect(org?.plan).toBe("free");
  });

  it("prorates an active seat increase and ignores removals and trials", async () => {
    const tenant = await createTenant("seats-prorate", "starter");
    await subscriptionRepo.updateSubscriptionBilling(
      tenant.org.id,
      {
        status: "active",
        interval: "monthly",
        seats: 2,
        currentPeriodStart: toIsoTimestamp(new Date("2026-03-01T00:00:00.000Z")),
        currentPeriodEnd: toIsoTimestamp(new Date("2026-03-31T00:00:00.000Z")),
      },
      new Date("2026-03-01T00:00:00.000Z"),
    );
    await subscriptionRepo.updateSeatCount(tenant.org.id, 2);

    // 10 days left of a 30-day period. 900 * 3 seats added * 1 month * 10/30 = 900.
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-03-21T00:00:00.000Z"));
    await billingService.updateSeats(tenant.actors.owner, {
      orgId: tenant.org.id,
      seats: 5,
    });
    const added = await invoiceRepo.listInvoices(tenant.org.id);
    expect(added).toHaveLength(1);
    expect(added[0]?.amountCents).toBe(900);
    expect(added[0]?.periodStart).toBe("2026-03-01T00:00:00.000Z");
    expect(added[0]?.periodEnd).toBe("2026-03-31T00:00:00.000Z");

    const period = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(period?.currentPeriodEnd).toBe("2026-03-31T00:00:00.000Z");
    expect(period?.seats).toBe(5);

    await billingService.updateSeats(tenant.actors.owner, {
      orgId: tenant.org.id,
      seats: 3,
    });
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(1);
    vi.useRealTimers();

    const trial = await createTenant("seats-trial", "starter");
    await billingService.updateSeats(trial.actors.owner, {
      orgId: trial.org.id,
      seats: 4,
    });
    expect(await invoiceRepo.listInvoices(trial.org.id)).toHaveLength(0);
  });

  it("charges a plan upgrade for the rest of the period and a free-to-paid move in full", async () => {
    const tenant = await createTenant("plan-prorate", "starter");
    await subscriptionRepo.updateSubscriptionBilling(
      tenant.org.id,
      {
        status: "active",
        interval: "annual",
        seats: 2,
        currentPeriodStart: toIsoTimestamp(new Date("2026-01-01T00:00:00.000Z")),
        currentPeriodEnd: toIsoTimestamp(new Date("2027-01-01T00:00:00.000Z")),
      },
      new Date("2026-01-01T00:00:00.000Z"),
    );
    await subscriptionRepo.updateSeatCount(tenant.org.id, 2);

    // 100 days left of 365. diff per seat = 1000. full = 1000 * 2 * 12 = 24000.
    // prorated = floor(24000 * 100 / 365) = floor(6575.342) = 6575.
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-09-23T00:00:00.000Z"));
    const upgraded = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "monthly",
    });
    expect(upgraded.plan).toBe("growth");
    expect(upgraded.currentPeriodStart).toBe("2026-01-01T00:00:00.000Z");
    expect(upgraded.currentPeriodEnd).toBe("2027-01-01T00:00:00.000Z");
    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]?.amountCents).toBe(6_575);

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(1);
    vi.useRealTimers();

    const free = await createTenant("plan-leave-free", "free");
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-05-31T06:00:00.000Z"));
    const paid = await billingService.changePlan(free.actors.owner, {
      orgId: free.org.id,
      plan: "starter",
      interval: "annual",
    });
    expect(paid.currentPeriodStart).toBe("2026-05-31T06:00:00.000Z");
    expect(paid.currentPeriodEnd).toBe("2027-05-31T06:00:00.000Z");
    expect(paid.status).toBe("active");
    const full = await invoiceRepo.listInvoices(free.org.id);
    // price 900 * 1 seat * 12
    expect(full).toHaveLength(1);
    expect(full[0]?.amountCents).toBe(10_800);
    vi.useRealTimers();

    const duringTrial = await createTenant("plan-during-trial", "starter");
    const before = await subscriptionRepo.findSubscription(duringTrial.org.id);
    await billingService.changePlan(duringTrial.actors.owner, {
      orgId: duringTrial.org.id,
      plan: "growth",
      interval: "annual",
    });
    const after = await subscriptionRepo.findSubscription(duringTrial.org.id);
    expect(after?.status).toBe("active");
    expect(after?.plan).toBe("growth");
    expect(after?.currentPeriodEnd).toBe(before?.currentPeriodEnd);
    expect(await invoiceRepo.listInvoices(duringTrial.org.id)).toHaveLength(0);
  });
});
